insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_tech_v1'
from (values
('126.19.c.6',3,'A student sorts survey results in a spreadsheet from highest to lowest. This is an example of...','["organizing data to find patterns", "deleting the data", "printing blank pages", "encrypting the data"]'::jsonb,0,'Sorting and filtering help analyze data.','original'),
('126.19.c.6',3,'Which tool is best for turning rows of eighth-grade quiz scores into a quick summary of the class average?','["a video filter", "a spreadsheet formula", "a drawing brush", "a slideshow transition"]'::jsonb,1,'Formulas such as AVERAGE analyze data.','original'),
('126.19.c.7',3,'A student wants to show how a school''s lunch sales changed each month. The best digital product is a...','["plain list of file names", "blank poster", "line chart", "audio clip of silence"]'::jsonb,2,'Line charts show change over time.','original'),
('126.19.c.7',3,'Before publishing a chart for an audience, a student should make sure it has...','["no numbers at all", "a hidden legend and no title", "random colors only", "a clear title and labeled axes"]'::jsonb,3,'Labels help viewers read the data.','original'),
('126.19.c.1.A',3,'Writing the steps for making a sandwich in plain language before coding is called...','["pseudocode", "rendering", "encryption", "compression"]'::jsonb,0,'Pseudocode outlines logic without strict syntax.','original'),
('126.19.c.1.A',3,'Breaking a big app idea into smaller tasks such as login, menu and score keeping is...','["duplication", "decomposition", "formatting", "deletion"]'::jsonb,1,'Decomposition splits a problem into parts.','original'),
('126.19.c.1.B',3,'In the pseudocode ''SET sum TO 0; REPEAT 5 TIMES: ADD 2 TO sum'', which word is the variable?','["REPEAT", "ADD", "sum", "TIMES"]'::jsonb,2,'A variable stores a changing value.','original'),
('126.19.c.1.B',3,'In pseudocode, the same pair of steps appearing again and again most likely shows a...','["file extension", "missing monitor", "syntax error that cannot be fixed", "pattern that could become a loop"]'::jsonb,3,'Repeated steps suggest iteration.','original'),
('126.19.c.1.C',3,'A student writes one algorithm that finds the largest number in any list, not just one list. The student used...','["abstraction", "hardware repair", "cropping", "plagiarism"]'::jsonb,0,'Abstraction generalizes a solution.','original'),
('126.19.c.1.C',3,'Which algorithm is more abstract?','["Type 4, 9, 2", "Find the biggest value in any list of numbers", "Find the biggest value in the list 4, 9, 2", "Print the number 9"]'::jsonb,1,'The general version works for many inputs.','original'),
('126.19.c.1.D',3,'A project plan written in pseudocode with a timeline helps a team to...','["hide mistakes", "skip testing", "agree on the problem, the solution and when each part is due", "avoid talking to each other"]'::jsonb,2,'Collaborative plans include a timeline.','original'),
('126.19.c.1.D',3,'Which item belongs in a team''s collaborative pseudocode plan?','["unrelated passwords", "the cafeteria menu", "a list of favorite songs", "the problem statement and possible solutions"]'::jsonb,3,'A plan documents the problem and solutions.','original'),
('126.19.c.1.E',3,'Two students solve the same task with different algorithms. To decide which is better, they should...','["compare how many steps and how accurate each one is", "flip a coin and never test", "pick the one with the fanciest name", "pick the longer one"]'::jsonb,0,'Compare and improve by testing efficiency and accuracy.','original'),
('126.19.c.1.E',3,'After testing an algorithm and finding it skips the last item in a list, the best next step is to...','["rename the file only", "revise the algorithm and test again", "delete the whole project", "ignore the bug"]'::jsonb,1,'Improve algorithms through revision.','original'),
('126.19.c.1.F',3,'A program must print the same message 50 times. Which approach is better?','["Copy the program to 50 computers", "Print it once and hope", "Use a loop that repeats 50 times", "Type the print line 50 times"]'::jsonb,2,'Iteration shortens code and reduces mistakes.','original'),
('126.19.c.1.F',3,'A key benefit of iteration in an algorithm is that it...','["removes the need for variables", "prevents all errors", "makes the code run on paper", "repeats steps without rewriting them"]'::jsonb,3,'Loops repeat sequences efficiently.','original'),
('126.19.c.2.A',3,'A variable that stores the text ''Maria'' has the data type...','["string", "Boolean", "float", "integer"]'::jsonb,0,'Text is stored as a string.','original'),
('126.19.c.2.A',3,'If score = 10 and the program runs score = score + 5, the new value of score is...','["105", "15", "5", "10"]'::jsonb,1,'Adding 5 to 10 gives 15.','original'),
('126.19.c.2.B',3,'A program prints a multiplication table using one loop for rows and another loop inside it for columns. This is a...','["broken loop", "stored variable", "nested loop", "network packet"]'::jsonb,2,'A loop within a loop is nested.','original'),
('126.19.c.2.B',3,'If an outer loop runs 3 times and an inner loop runs 4 times each time, the inner steps run a total of...','["7 times", "4 times", "3 times", "12 times"]'::jsonb,3,'3 x 4 = 12.','original'),
('126.19.c.2.C',3,'A student copies a classmate''s game with permission, then changes the speed and adds a new level. This is...','["modifying existing code to improve it", "starting from nothing", "hacking the school network", "deleting the game"]'::jsonb,0,'Modify and implement previously written code.','original'),
('126.19.c.2.C',3,'When modifying someone else''s code, a good habit is to...','["delete all comments", "read it, add comments and test each change", "claim it as entirely your own work", "change everything at once untested"]'::jsonb,1,'Careful changes plus credit keep code reliable and honest.','original'),
('126.19.c.3.A',3,'A student who sets a goal, tries a new idea and learns from a failed test is showing...','["fear of changes", "copying without thought", "calculated risk-taking in design", "refusing to plan"]'::jsonb,2,'Innovation includes calculated risks.','original'),
('126.19.c.3.A',3,'Which character trait most helps a designer keep improving after a prototype fails?','["blaming others", "giving up", "impatience", "perseverance"]'::jsonb,3,'Perseverance supports innovation.','original'),
('126.19.c.3.B',3,'In a design process, testing a prototype helps the designer to...','["find design limitations to fix", "avoid all feedback", "hide the product", "skip planning"]'::jsonb,0,'Testing and evaluating reveal limits.','original'),
('126.19.c.3.B',3,'Which sequence best matches a design process?','["publish, plan, delete, test", "plan, develop, test, evaluate", "evaluate, hide, delete, quit", "test, forget, publish, plan"]'::jsonb,1,'Design moves from planning to evaluation.','original'),
('126.19.c.3.C',3,'An architect drafts a blueprint, a game studio builds a prototype, and a chef tests a recipe. This shows...','["only one job uses design", "testing is unnecessary", "the design process is used in many industries", "design is never repeated"]'::jsonb,2,'Many fields use a design process.','original'),
('126.19.c.3.C',3,'Which industry uses a design process to create new products?','["only restaurants", "only libraries", "none of them", "automotive manufacturing"]'::jsonb,3,'Car makers design, test and revise products.','original'),
('126.19.c.4.A',3,'The printing press, the telephone and the internet each changed how people share information. This shows how technology has...','["affected many areas of study over time", "stayed the same forever", "had no effect on history", "stopped all learning"]'::jsonb,0,'Technology changes fields throughout history.','original'),
('126.19.c.4.A',3,'How has digital imaging most changed the study of medicine?','["Medicine stopped using science", "Doctors can view detailed scans inside the body", "Doctors no longer study anatomy", "Patients stop needing checkups"]'::jsonb,1,'Imaging technology advanced medical study.','original'),
('126.19.c.4.B',3,'Growing demand for clean energy is a global trend that is leading to...','["the end of electricity", "fewer inventions", "new technology such as better solar panels and batteries", "no new research"]'::jsonb,2,'Global trends drive technology development.','original'),
('126.19.c.4.B',3,'A prediction based on the global trend of more people using smartphones could be that...','["nobody will use apps", "phones will disappear tomorrow", "websites will never change", "more services will be designed for mobile devices"]'::jsonb,3,'Trends help predict technology development.','original'),
('126.19.c.4.C',3,'A student who knows how to use one photo editor can learn a new one faster by...','["transferring what they know about layers and tools", "refusing to try it", "starting with zero knowledge", "waiting for someone else to do it"]'::jsonb,0,'Transferring knowledge speeds learning new technology.','original'),
('126.19.c.4.C',3,'Which action best shows transferring knowledge to a new technology?','["Throwing out your notes", "Using what you know about one slideshow app to learn another", "Asking for the answer without trying", "Avoiding the new app"]'::jsonb,1,'Prior knowledge applies to new tools.','original'),
('126.19.c.5.A',3,'In the binary system, data is represented using only...','["red and blue", "1 through 9", "0 and 1", "A through Z"]'::jsonb,2,'Binary uses two digits.','original'),
('126.19.c.5.A',3,'Which data type can only be true or false?','["real number", "string", "integer", "Boolean"]'::jsonb,3,'Booleans hold true/false values.','original'),
('126.19.c.5.B',3,'A student searches for ''solar AND wind'' to find pages that...','["include both terms", "include neither term", "include only one term", "hide all results"]'::jsonb,0,'AND narrows a search to both keywords.','original'),
('126.19.c.5.B',3,'Which search limiter helps find only recent results?','["a brighter screen", "a date range filter", "a larger font", "a louder sound"]'::jsonb,1,'Limiters narrow results, such as by date.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_tech_v1'
from (values
('126.19.c.8.A',3,'A digital footprint is the...','["speed of your internet", "length of your keyboard", "trail of data you leave online", "size of your computer screen"]'::jsonb,2,'Your posts and activity form your footprint.','original'),
('126.19.c.8.A',3,'Why should you think before posting online?','["They never affect anything", "Posts always disappear instantly", "Nobody can ever see them", "Posts can stay public and affect your future opportunities"]'::jsonb,3,'A footprint can last for years.','original'),
('126.19.c.8.B',3,'A formal email to an international audience should use...','["clear, polite language and a proper greeting", "all capital letters", "private jokes", "slang and emojis only"]'::jsonb,0,'Formal digital etiquette suits a global audience.','original'),
('126.19.c.8.B',3,'When writing for readers around the world, it is best to avoid...','["correct spelling", "slang that may not translate", "clear sentences", "a courteous tone"]'::jsonb,1,'Plain language reaches a global audience.','original'),
('126.19.c.8.C',3,'Students in two countries make a video together. They should plan for...','["deleting each other''s work", "no communication at all", "different time zones and respectful communication", "ignoring each other''s ideas"]'::jsonb,2,'Global collaboration requires planning and respect.','original'),
('126.19.c.8.C',3,'A formal presentation video differs from a casual vlog because it uses...','["no audience in mind", "only inside jokes", "no editing", "planned script and professional tone"]'::jsonb,3,'Formal communication is planned and polished.','original'),
('126.19.c.9.A',3,'A school''s acceptable use policy (AUP) tells students...','["the rules for using school technology", "how to play sports", "what to eat for lunch", "when recess ends"]'::jsonb,0,'An AUP sets technology rules.','original'),
('126.19.c.9.A',3,'Which choice shows safe, ethical online behavior?','["Sharing someone''s password", "Reporting cyberbullying to a trusted adult", "Posting a classmate''s private photo", "Pretending to be someone else"]'::jsonb,1,'Positive behavior includes reporting harm.','original'),
('126.19.c.9.B',3,'A student wants to use a song in a school video. To follow intellectual property law, the student should...','["ignore the creator completely", "copy any song and claim it", "use music with permission or a proper license", "remove the artist''s name and say it''s theirs"]'::jsonb,2,'Respect copyright by getting permission.','original'),
('126.19.c.9.B',3,'Which of these is usually free to use with credit because the creator allows it?','["a paid stock photo copied without buying", "any image found online", "a photo marked all rights reserved", "an image with a Creative Commons license"]'::jsonb,3,'Creative Commons licenses grant permissions.','original'),
('126.19.c.9.C',3,'A citation for a website should usually include the...','["author, title, website name and date or URL", "teacher''s nickname", "computer''s serial number", "student''s lunch order"]'::jsonb,0,'Citations let readers find the source.','original'),
('126.19.c.9.C',3,'A student uses a video as a source in a research slide. The student should...','["leave out the source", "cite the video''s creator and title", "cite only a random website", "claim they filmed it"]'::jsonb,1,'All digital media need citations.','original'),
('126.19.c.9.D',3,'A website selling a product says it is ''the only choice'' and has no named author. This site may be...','["always neutral", "a peer-reviewed study", "biased", "always accurate"]'::jsonb,2,'Sales language and missing authors signal bias.','original'),
('126.19.c.9.D',3,'To check if an online source is biased, a student should...','["assume ads mean it is true", "trust the loudest headline", "trust the first result", "compare it with other reliable sources"]'::jsonb,3,'Cross-checking helps evaluate bias.','original'),
('126.19.c.10.A',3,'An email says ''Click here now or your account will be deleted'' and links to an unknown site. This is most likely...','["phishing", "a school newsletter", "a software update from your device settings", "a friendly reminder"]'::jsonb,0,'Urgent threats and strange links signal phishing.','original'),
('126.19.c.10.A',3,'A good way to prevent harm from a phishing message is to...','["enter your password to test it", "not click the link and report it", "click the link to check", "forward it to all your friends"]'::jsonb,1,'Avoid and report suspicious messages.','original'),
('126.19.c.10.B',3,'Which could be a warning sign that a student is being cyberbullied?','["joining a club happily", "winning a game", "withdrawing from friends and sleeping poorly", "finishing homework early"]'::jsonb,2,'Withdrawal and sleep changes are warning signs.','original'),
('126.19.c.10.B',3,'A friend seems upset after reading their phone and avoids school. The best response is to...','["join the bullying", "spread the messages", "ignore it completely", "support them and tell a trusted adult"]'::jsonb,3,'Support and adult help reduce harm.','original'),
('126.19.c.11.A',3,'A student combines text, a photo and a short audio clip into one presentation. This is...','["combining file formats for an audience", "deleting a file", "renaming a folder", "formatting a drive"]'::jsonb,0,'Projects often mix formats.','original'),
('126.19.c.11.A',3,'Which format is best for a logo that must stay sharp at any size?','["low-quality raster image", "vector graphic", "audio file", "plain text file"]'::jsonb,1,'Vector graphics scale without losing quality.','original'),
('126.19.c.11.B',3,'Sharing a draft video with classmates and asking for comments helps you to...','["avoid learning", "hide mistakes", "improve the project with feedback", "delay forever"]'::jsonb,2,'Feedback improves digital products.','original'),
('126.19.c.11.B',3,'Which is a raster graphic file type?','["DOCX", "SVG", "MP3", "JPEG"]'::jsonb,3,'JPEG images are made of pixels.','original'),
('126.19.c.12.A',3,'Which sentence correctly uses technology terminology?','["The router connects my laptop to the network.", "The RAM is a kind of keyboard.", "The cookie flew across the monitor.", "The cursor is stored in the cloud only."]'::jsonb,0,'Accurate vocabulary supports clear discussion.','original'),
('126.19.c.12.A',3,'Using precise terms such as ''bandwidth'' and ''download'' in class discussion shows...','["random guessing", "scholarly use of technology language", "confusion about computers", "an attempt to avoid the topic"]'::jsonb,1,'Terminology is part of academic dialogue.','original'),
('126.19.c.12.B',3,'Which file name is clearest for a science project saved in November?','["new new final", "stuff", "Science_Project_Nov_v2", "asdf123"]'::jsonb,2,'Good file names describe content and version.','original'),
('126.19.c.12.B',3,'An effective file management strategy is to...','["keep everything on the desktop", "store only one copy", "use no names", "organize files in folders and keep backups"]'::jsonb,3,'Hierarchy and backup protect work.','original'),
('126.19.c.12.C',3,'To move a large project to another computer, a student could use...','["a USB flash drive or cloud storage", "a mouse pad", "a keyboard", "a printer cable only"]'::jsonb,0,'Select tools suited to transferring data.','original'),
('126.19.c.12.C',3,'A student needs to print a document. The right hardware is a...','["scanner", "printer", "webcam", "microphone"]'::jsonb,1,'Printers produce paper copies.','original'),
('126.19.c.12.D',3,'To improve typing speed and accuracy, a student should practice...','["looking at the keys only", "typing with two fingers", "correct finger placement on the home row", "ignoring errors"]'::jsonb,2,'Proper technique raises words per minute.','original'),
('126.19.c.12.D',3,'Typing speed is measured in...','["hertz", "pixels per inch", "megabytes per second", "words per minute"]'::jsonb,3,'WPM measures keyboarding speed.','original'),
('126.19.c.12.E',3,'On most Windows computers, Ctrl + C is the shortcut to...','["copy", "capture a video", "close", "cut the cord"]'::jsonb,0,'Ctrl+C copies selected content.','original'),
('126.19.c.12.E',3,'The keyboard shortcut Ctrl + Z usually...','["opens a new window", "undoes the last action", "zooms in", "saves a file as a zip"]'::jsonb,1,'Ctrl+Z is Undo.','original'),
('126.19.c.12.F',3,'A computer program freezes. A good first troubleshooting step is to...','["ignore it forever", "type random commands", "restart the program or device", "throw the computer away"]'::jsonb,2,'Simple fixes come first.','original'),
('126.19.c.12.F',3,'If basic troubleshooting does not fix a problem, a student should...','["open every setting", "hide the issue", "give up on learning", "ask a teacher or technical support"]'::jsonb,3,'Seeking help is part of troubleshooting.','original'),
('126.19.c.12.G',3,'Cloud storage lets you access files from...','["any device with an internet connection", "nowhere", "only one computer", "only a paper folder"]'::jsonb,0,'Cloud files are stored remotely.','original'),
('126.19.c.12.G',3,'A local hard drive is best when you need to...','["avoid saving files", "work offline and keep files on one device", "store nothing", "share instantly with the world"]'::jsonb,1,'Local storage works without internet.','original'),
('126.19.c.12.H',3,'In a spreadsheet, cells A1 through A5 hold 2, 4, 6, 8 and 10. The formula =SUM(A1:A5) shows...','["10", "20", "30", "5"]'::jsonb,2,'2+4+6+8+10 = 30.','original'),
('126.19.c.12.H',3,'Which application is best for designing a school newsletter with columns and images?','["a file compressor", "a stopwatch", "a calculator app", "a publication application"]'::jsonb,3,'Publication software handles page layout.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
